// Extract primary media URL and type from each ad
// v2: Enhanced with ad metadata extraction for scoring, dedup by body text,
//     and capture of ad copy/CTA for structured analysis
const items = $input.all();
const results = [];
const seenBodies = new Set();

for (const item of items) {
  const ad = item.json;
  const snapshot = ad.snapshot || {};
  const displayFormat = (snapshot.displayFormat || '').toUpperCase();

  // Deduplicate by ad body text (same creative concept)
  const bodyText = (snapshot.body || {}).text || snapshot.bodyText || '';
  const bodyKey = bodyText.trim().substring(0, 120).toLowerCase();
  if (bodyKey && seenBodies.has(bodyKey)) continue;
  if (bodyKey) seenBodies.add(bodyKey);

  let primaryMediaUrl = null;
  let mediaType = null;
  let mediaFileExtension = null;
  let allMediaUrls = [];

  if (displayFormat === 'VIDEO') {
    const video = (snapshot.videos || [])[0];
    if (video) {
      primaryMediaUrl = video.videoHdUrl || video.videoSdUrl || null;
      mediaType = 'video';
      mediaFileExtension = 'mp4';
    }
  } else if (displayFormat === 'IMAGE') {
    const image = (snapshot.images || [])[0];
    if (image) {
      primaryMediaUrl = image.originalImageUrl || image.resizedImageUrl || null;
      mediaType = 'image';
      mediaFileExtension = 'jpg';
    }
  } else if (displayFormat === 'CAROUSEL' || displayFormat === 'DCO') {
    const cards = snapshot.cards || [];
    for (const card of cards) {
      const url = card.originalImageUrl || card.resizedImageUrl;
      if (url) allMediaUrls.push(url);
    }
    const card = cards[0];
    if (card) {
      primaryMediaUrl = card.originalImageUrl || card.resizedImageUrl || null;
      mediaType = 'image';
      mediaFileExtension = 'jpg';
    }
  } else {
    const card = (snapshot.cards || [])[0];
    const image = (snapshot.images || [])[0];
    const video = (snapshot.videos || [])[0];

    if (card && (card.originalImageUrl || card.resizedImageUrl)) {
      primaryMediaUrl = card.originalImageUrl || card.resizedImageUrl;
      mediaType = 'image';
      mediaFileExtension = 'jpg';
    } else if (image && (image.originalImageUrl || image.resizedImageUrl)) {
      primaryMediaUrl = image.originalImageUrl || image.resizedImageUrl;
      mediaType = 'image';
      mediaFileExtension = 'jpg';
    } else if (video && (video.videoHdUrl || video.videoSdUrl)) {
      primaryMediaUrl = video.videoHdUrl || video.videoSdUrl;
      mediaType = 'video';
      mediaFileExtension = 'mp4';
    }
  }

  const adCopy = {
    headline: (snapshot.title || snapshot.linkTitle || '').trim(),
    body: bodyText.trim(),
    cta: (snapshot.ctaText || snapshot.linkCaption || '').trim(),
    linkUrl: (snapshot.linkUrl || '').trim(),
    description: (snapshot.linkDescription || '').trim()
  };

  if (primaryMediaUrl) {
    results.push({
      json: {
        ...ad,
        primaryMediaUrl,
        allMediaUrls: allMediaUrls.length > 0 ? allMediaUrls : [primaryMediaUrl],
        mediaType,
        mediaFileExtension,
        displayFormat,
        adCopy,
        isActive: ad.isActive !== false,
        startDate: ad.startDate || ad.deliveryStartDate || null,
        adIndex: results.length
      }
    });
  }
}

return results;

const crypto = require('crypto');
const items = $input.all();
const mediaList = [];
const seen = new Set();

for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary?.data;
  const ad = $('extract_primary_media').all()[i]?.json;

  if (bin) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
      const hash = crypto.createHash('md5').update(buffer).digest('hex');

      if (!seen.has(hash)) {
        seen.add(hash);
        mediaList.push({
          mimeType: ad?.mediaType === 'video' ? 'video/mp4' : 'image/jpeg',
          base64: buffer.toString('base64'),
          adIndex: ad?.adIndex ?? i,
          format: ad?.displayFormat || 'UNKNOWN'
        });
      }
    } catch (e) {
      // Skip failed media downloads silently
    }
  }
}

return [{ json: { mediaList, totalItems: mediaList.length, deduped: items.length - mediaList.length } }];

