// Increment poll counter and check for max retries
const currentCount = ($('init_poll_counter').first().json.pollCount || 0) + 1;
const status = $json.status || 'unknown';
const maxPolls = 20; // ~10 minutes with 30s wait intervals

if (status === 'completed') {
  return [{ json: { ...($json), pollCount: currentCount, outcome: 'completed' } }];
}

if (status === 'failed' || status === 'error') {
  return [{ json: { ...($json), pollCount: currentCount, outcome: 'failed', error: $json.error || 'Gamma generation failed' } }];
}

if (currentCount >= maxPolls) {
  return [{ json: { ...($json), pollCount: currentCount, outcome: 'timeout', error: `Timed out after ${maxPolls} polls (~${maxPolls * 30}s)` } }];
}

// Still in progress — return for another wait cycle
return [{ json: { ...($json), pollCount: currentCount, outcome: 'pending' } }];
